+NS_IMETHODIMP FolderDatabase::GetFolderIsDescendantOf(
+    uint64_t folderId, uint64_t potentialAncestorId, bool* isDescendant) {
+  NS_ENSURE_ARG(folderId);
+  NS_ENSURE_ARG(potentialAncestorId);
